import heapq
from math import inf

def process_point(x, vertices, durability):
    stack = []
    for v in vertices:
        while stack and stack[0] > v:
            stack.pop(0)
        if not stack:
            continue
        slope = abs(x - v) / (vertices[stack[0]] - v)
        if slope > durability:
            return True
        heapq.heappush(stack, vertices[stack[0]])
    return False

def find_crash_point(vertices):
    left = 0
    right = len(vertices) - 1
    while left <= right:
        mid = (left + right) // 2
        if process_point(vertices[mid], vertices, 50 + vertices[-1] - 1e-9):
            right = mid - 1
        else:
            left = mid + 1
    return vertices[left]

def find_strength(vertices):
    vertices.sort()
    d = [1 + v[1] for v in vertices]
    a = b = float("inf")
    for i in range(len(d)):
        while process_point(vertices[i], vertices, d[i]):
            a = set([vertices[j][1] for j in range(i, len(vertices)) if process_point(vertices[j], vertices, d[j])])
            if a:
                break
    while process_point(b, vertices, d[-1] - 1e-9):
        b = b + 1
    return (a.portion() + a.last_value() + d[-1] - b) / 2

