import math

def maximize(nums):
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            dp[i][j] = float('inf')
            for k in range(i, j):
                op1 = dp[i][k] + dp[k + 1][j]
                op2 = dp[i][j-1] + sum(nums[i:j+1])
                dp[i][j] = min(dp[i][j], op1, op2)
    return dp[0][n-1]

def max_difference(nums):
    nums.sort()
    n = len(nums)
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        if nums[i] > nums[i+1]:
            dp[i] = math.inf
        else:
            k = bisect.bisect_right(nums, nums[i] - 1)
            dp[i] = min(dp[k - 1] + 1, dp[i + 1] + nums[i] - nums[k - 1], dp[i+1] + nums[i + 1] - nums[k], dp[i] + nums[i] - nums[k])
    return dp[0]

def max_min_diff(nums):
    return min(max_difference(nums), maximize(nums))

