from collections import defaultdict

def greedy_algorithm(n, k, edges):
    graph = defaultdict(set)
    for a, b in edges:
        graph[a].add(b)
        graph[b].add(a)

    red_nodes = set()
    blue_nodes = set()
    count = 0

    for v in range(2, n + 1):
        if v == 2 or v in red_nodes:
            if count <= k:
                if v not in red_nodes:
                    red_nodes.add(v)
                    count += 1

            for neighbor in graph[v]:
                if neighbor in red_nodes and neighbor not in blue_nodes:
                    blue_nodes.add(neighbor)

        else:
            for neighbor in graph[v]:
                blue_nodes.add(neighbor)

    red_count = len(red_nodes)
    blue_count = len(blue_nodes)

    if red_count == n - 2 or blue_count > n // 2:
        return -1
    else:
        return red_count * (red_count - blue_count)

