import heapq

def min_max_difference(costs, prices, special_nodes, source, destination):
    # Build the graph
    graph = {i: [] for i in range(1, len(costs) + 1)}
    for u, v in enumerate(costs, 1):
        graph[u].append(v)

    # Build the cost dictionaries
    node_price = {i: prices[i-1] for i in source}
    pivot_cost = {node: costs[node-1] - node_price[i-1] for node in special_nodes + [i-1 for i in source]}
    source_node_price = {node: node_price[i-1] for i, special_node in enumerate(prices) for node in special_nodes if i == special_node}

    min_heap = [[pivot_cost[node], node] for node in special_nodes if node != source[0]]
    heapq.heapify(min_heap)

    heap = [(-destination, source[0], 0, source[0])]

    while heap:
        price, pivot_node, price_so_far, current_node = heapq.heappop(heap)
        if current_node == destination:
            break
        if cost := pivot_cost(pivot_node):
            if node := sum(prices if price_so_far < price - cost else prices - (price_so_far + cost)):
                old_price = price_so_far + cost
                heapq.heappush(min_heap, (price - cost, pivot_node)) if old_price >= node_price[pivot_node] else heapq.heappush(min_heap, (old_price + cost, pivot_node))

            if current_price := price_so_far + cost:
                next_index = len(costs) - 1
                while next_index > destination and source_node_price.get(next_index) != current_price:
                    next_index -= 1

                if node := sum(prices if current_price - prices[next_index] < costs[next_index] else prices - (current_price - prices[next_index])):
                    old_cost = str(node - node_price[pivot_node])
                    heapq.heappush(min_heap, (price - cost, pivot_node)))

                    if current_price <= prices[next_index]:
                        node -= price_so_far + cost
                        if next_node := sum(prices):
                            heapq.heappush(heap, (next_node, next_index, old_cost, next_index))
    if not min_heap:
        return 0
    path_value, chosen_segment = min_heap[0]
    return path_value if path_value <= destination + node else 0

