from collections import deque
from typing import List, Tuple

class Campus:
    def __init__(self, n: int):
        self.dormitories = [None] * n
        self.universities = {i: i for i in range(n)}
        self.military_offices = {i: i for i in range(n)}
        self.dormitories_count = [1] * n
        self.university_dormitories_count = [1] * n
        self.military_office_dormitories_count = [1] * n

    def merge_universities(self, aj: int, bj: int) -> None:
        if aj == bj:
            return
        jb = self.universities[bj]
        for i in range(jb):
            self.universities[i] = aj
            self.dormitories[i] = aj
            self.university_dormitories_count[aj] -= self.dormitories_count[i]
            self.dormitories_count[i] = 0
        del self.universities[bj]
        self.university_dormitories_count[aj] += self.university_dormitories_count.pop(jb)

    def merge_military_offices(self, cj: int, dj: int) -> None:
        if dj == cj:
            return
        j = self.military_offices[dj]
        for i in range(j):
            self.military_offices[i] = cj
            self.dormitories[i] = cj
            self.military_office_dormitories_count[cj] -= self.dormitories_count[i]
            self.dormitories_count[i] = 0
        del self.military_offices[dj]
        self.military_office_dormitories_count[cj] += self.military_office_dormitories_count.pop(dj)

    def move_students_to_dormitories(self, x: int) -> Tuple[int, List[bool]]:
        dx = []
        for i in range(len(self.dormitories)):
            if self.dormitories[i] != x:
                if self.dormitories_count[i]:
                    dx.append((i, self.university_dormitories_count[x] + self.dormitories_count[i]))
                self.dormitories_count[i] = 0
        return len(dx), dx

    def raid_military_office(self, y: int) -> None:
        ix = self.military_office_dormitories_count[y]
        difference, dormitories = self.move_students_to_dormitories(x=-1)
        for d in dormitories:
            self.dormitories[d[0]] = y
            self.copy_dormitories(d)
        del self.military_office_dormitories_count[y]
        self.military_office_dormitories_count[y] += ix
        return difference

    def query(self, qj: int) -> int:
        if self.dormitories[qj]:
            return len(self.dormitories)
        i, dx = self.move_students_to_dormitories(x=-1)
        difference = len(dx)
        for d in dx:
            self.dormitories[d[0]] = self.dormitories[qj]
            self.copy_dormitories(d)
        return difference

    def copy_dormitories(self, d):
        for i in range(d[0], d[1]):
            self.dormitories[i] = self.dormitories[d[0]]

    def __repr__(self):
        return '/'.join(str(i) for i in self.dormitories) + '/' + '/'.join(str(i) for i in self.universities.values()) + '/' + '/'.join(str(i) for i in self.military_offices.values())

def process_queries(n: int, m: int, queries: List[str]) -> List[int]:
    campus = Campus(n)
    university_merged = 0
    military_office_merged = False
    university_and_military_office_merged = False
    previous = None
    out = []
    for query in queries:
        if query.startswith('U'):
            (aj, bj) = [int(i) - 1 for i in query.split()]
            campus.merge_universities(aj, bj)
        elif query.startswith('M'):
            (cj, dj) = [int(i) - 1 for i in query.split()]
            campus.merge_military_offices(cj, dj)
        elif query.startswith('A'):
            university_and_military_office_merged = True
            previous = query
        elif query.startswith('Z'):
            (yj,) = [int(i) - 1 for i in query.split()]
            if military_office_merged:
                difference = campus.raid_military_office(yj)
                if difference:
                    out.append(difference)
                else:
                    out.append(0)
                university_and_military_office_merged = False
                university_merged += 1
