def bellman_ford(graph, src, destination):
    dist = {}
    pq = [(0, src)]
    while pq:
        d, u = pq[0]
        heapq.heappop(pq)
        if u in dist:
            continue
        dist[u] = d
        for v, weight in graph[u].items():
            if v not in dist:
                heapq.heappush(pq, (weight + d, v))
    return dist[destination]

def main():
