        current_lca = None
        for i in range(len(lca)):
            if lca[u][i] == lca[v][i]:
                current_lca = lca[u][i] if current_lca is None else current_lca
        src, dest, value = u, v, w
        total_cost = costs[src] + costs[dest]
        best_path = i for i in range(len(lca)) if total_cost <= i
        distanceeded_points = set()
        best_path_value = value
        while best_path:
            candidate = best_path.pop()
            if lca[src][candidate] == lca[dest][candidate]:
                neighboring_lca = lca[src][candidate]
            else:
                neighboring_lca = lca[src][candidate]
                if neighboring_lca not in dist:
                    current_lca = lca[neighboring_lca][candidate]
                    while neighboring_lca != current_lca:
                        current_lca = lca[current_lca][neighboring_lca]
                        dist_end = (total_cost - costs[neighboring_lca]
                                    - costs[current_lca + 1 - k])
                        if dist_end < 0:
                            break
                        else:
                            d = heapq.heappop(dist_end)
                        dist_end[k] = d
                        if d < dist_end[-1]:  # corresponds to reducer efficiency
                            dist = dist_end[::k]
                        heapq.heappush(distanceeded_points, candidate)
                        candidate = neighboring_lca
            if current_lca <= dest:
                if dst in dist:
                    best_path_value += costs[dst]
                    best_path_value = min(best_path_value, total_cost)
                break
            best_path_value += costs[candidate]
            best_path_value = min(best_path_value, total_cost)
            heapq.heappush(distanceeded_points, candidate)
            candidate = lca[current_lca][current_lca]
    print(best_path_value)

