from collections import defaultdict

def max_lines(n, m):
    if n == 0 or n == 1:
        return 1, n
    elif n == 2:
        return len(set(m)) + 1, 1
    else:
        left, k_left = max_lines(n - 1, m)
        right = len(m) - len(set(m) - set((i * (i - 1) // 2 for i in m)))
        last_right = min([right, m.count(k) + 1 for k in set(m)])
        return left + last_right, max(left + k_left, k_left + right)

def min_lines(n):
    if n == 0:
        return 0, 1
    elif n == 1:
        return 1, 1
    elif n == 2:
        return 2, 1
    elif n == 3:
        return 3, 2
    elif n == 4:
        return 3, 2
    else:
        m = set()
        for i in range(1, n + 1):
            for j in range(n - i + 1, n + 1):
                m.add(i * j)
        l1 = len(m) - len(set((i * (i - 1) // 2 for i in m)))
        l2, k_l2 = min_lines(len(m) // 2)
        k_l2 += l2 + 1
        k_l1 = len(m) - l1
        l1, k_l1 = min_lines(len(m) - l1)
        if max(l1, l2) < k_l1:
            return k_l1, k_l2 + l2 + 1
        return k_l1, k_l2 + l2 + l1 + 1

