class ElevatorSimulator:
    def find_min_time(self, n, employees):
        people = []
        for i, (start_floor, dest_floor) in enumerate(employees):
            heappush(people, (dest_floor - start_floor, i))

        cur_floor = 1
        prev_floor = -1
        prev_people = None
        time = 0
        while len(people) > 0:
            if prev_floor > 1:
                time += 2  # Move up and open doors
            minute = heappop(people)
            curr_people = minute[1]

            if prev_people is not None and prev_people > curr_people:
                time += 2  # Move down and open doors

            for _ in range(min(4 - len(people), 4)):
                if prev_floor > 1:
                    time += 2  # Move up and open doors
                prev_floor += 1
            for _ in range(4):
                time += 1  # Wait until it’s time

                if prev_people is None:
                    time += 1  # Open doors
                    for _ in range(4):
                        time += 1  # Enter employees
                        time += 1  # Open doors again (departure)
                else:
                    for _ in range(4 - prev_people):
                        time += 1  # Wait for the requested number of people to leave 
                    prev_people, _ = heappop(people)
                    time += 1  # Go up
                    for _ in range(4):
                        time += 1  # Open doors
                    for _ in range(4):
                        time += 1  # Enter employees
                    if len(people) > 0 and len(people) == 1 and people[0][0] == cur_floor:
                        prev_floor = -1  # Change direction
                        time += 1  # Open doors
                    for _ in range(len(people) - 4):
                        time += 1  # Wait for the remaining people to get out

                if cur_floor > prev_floor:
                    time += 2  # Move down and open doors

            prev_floor, prev_people = cur_floor, curr_people
        return time

    def simulate_all_multis(self):
        n = int(stdin.readline())
        employees = [list(map(int, stdin.readline().split())) for _ in range(n)]
        return self.find_min_time(n, employees)

