import math

def get_intersections(durations):
    intersections = 0
    for i in range(1, len(durations) - 1):
        if durations[i] % 2 == 0:
            intersections += 1
    return intersections

def find_min_durability(n, coordinates, durations):
    potential_x = 10 * [0]  # Tracks current allowed x locations
    for i in range(n):
        current = coordinates[i + 1] - coordinates[i]
        new_x = 0
        start = 0
        end = len(potential_x) - 1
        while start + 1 < end:
            mid = (start + end) // 2
            if current >= potential_x[mid]:
                new_x = mid
                start = mid
            else:
                end = mid
        if start < len(potential_x):
            if durations[start] % 2 != 0:
                intersections = get_intersections(durations[start:])
                if intersections < 2000:
                    potential_x[start] = int(math.ceil(potential_x[start] + 0.1))
                    potential_x[new_x - 1] = int(min(potential_x[new_x - 1], potential_x[start]))
                elif start > -1 and durations[start] % 2 != 0:
                    if intersections == 1:
                        potential_x[start] = int(math.ceil(potential_x[start] + 3))  # Exceptional case
                        intersections = 0
                    else:
                        intersections = 0
                        potential_x[start] = 0
        else:
            if durations[start] % 2 != 0:
                intersections = get_intersections(durations[start:])
                if intersections < 2000:
                    potential_x[start - 1] = int(max(potential_x[start - 1], potential_x[start])
                                                + 0.2))
                elif start > -1 and durations[start] % 2 != 0:
                    if intersections == 1:
                        potential_x[start] = int(math.ceil(potential_x[start] + 3))  # Exceptional case
                        intersections = 0
                    else:
                        intersections = 0
                        potential_x[start + 1] = 0
    return min(potential_x)

