from collections import defaultdict
import sys

def build_tree(n, p, parent):
    for i in range(1, n):
        parent[i] = p[i-1]
    return parent

def find_parent(parent, x):
    if parent[x] == x:
        return x
    parent[x] = find_parent(parent, parent[x])
    return parent[x]

def union_sets(x, y, parent):
    root_x = find_parent(parent, x)
    root_y = find_parent(parent, y)
    if root_x != root_y:
        parent[root_x] = root_y

def query(i, j, p, parent):
    for node in range(2, i+1):
        p_i = parent[node-1]
        if p_i != j:
            yield (p_i, parent[p_i-1])

def mex(v):
    return next(i for i in range(len(v)) if v[i] == i)

def solve_queries(n, q, queries):
    parent = [-1] * (n + 1)
    tree = [0] * (n + 1)
    for i in range(1, n + 1):
        tree[p[i-1]] += 1
    parent = build_tree(n, p, parent)
    answers = []

    for _ in range(q):
        t, i, j = queries[_]
        if t == 1:
            current_frequency = tree[i]
            tree[i] = tree[j]
            tree[j] = current_frequency
            union_sets(i, j, parent)
        elif t == 2:
            ans = 0
            for j, parent_node in query(i, j, p, parent):
                current_frequency = tree[j]
                tree[j] = tree[parent_node]
                tree[parent_node] = current_frequency
                current_mex = mex(tree)
                if current_mex > 0: 
                    ans = max(ans, current_mex + 1)
            answers.append(ans)
    return answers

