def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def is_prime(n):
    return n > 1 and all(n % d for d in range(2, int(n**0.5) + 1))

def is_prime_in_range(n, m):
    return all((p % m == 0 and is_prime(p)) or p < m for p in prime_factors(n))

def process_queries(edges: List[List[int]], queries: List[List[int]]):
    parent = [i for i in range(len(edges) + 1)]
    prime_factor_count = defaultdict(lambda: [0, 0])

    def build_tree(start=1, end=len(edges)):
        if start == end:
            return
        mid = (start + end) // 2
        build_tree(start, mid)
        build_tree(mid + 1, end)
        for u, v in edges[mid]:
            parent[u] = parent[v] = mid

    # Convert queries into a format that works with prime factors
    queries = [[1, i, x] for i, x in enumerate(queries)]
    queries.extend([[2, i] for i in range(1, len(edges) + 1)])

    build_tree()

    # Process queries based on the type
    for operation, v, x in sorted(queries):
        if operation == 1:
            for u in prime_factor_count[v][1]:
                prime_factor_count[u][1] += 1
        elif operation == 2:
            if is_prime_in_range(edges[0][0], edges[0][-1], x):
                prime_factor_count[v][0] += 1

    result = []
    for index, (operation, v) in enumerate(sorted(queries, key=lambda x: x[1])):
        if operation == 1:
