                count = (v - parent[u] + 1) * (v + x // edges[0][-1]) // 2
                u_f, v_f, unused_prime = prime_factor_count[u]
                q = prime_factor_count[u][0] + count * v_f // u_f
                result.append(q)
        elif operation == 2:
            result.append(prime_factor_count[v][0])

    return result

