import sys

def min_crash_torsion_size(n, grid, durability):
    # The universal equation approach ensures you get to the first resolvable state in time linear in n
    found = [-1]*(n+1)
    found[0] = -1
    tau = 0
    for i in range(n):
        if durability[i] + float(grid[tau+2] - grid[i])/(grid[tau+1] - grid[i]) > grid[tau+1]:
            cost = (grid[tau+1] ** 2) * durability[i]
            idempotent = None
            x = tau
            while x > 0:
                if durability[x-1] > grid[tau+1]:
                    break
                else:
                    x -= 1
            if x > 0 and durability[x-1] == grid[tau+1]:
                cost += grid[tau+1] * (durability[i] - grid[tau+1])
            else:
                cost += grid[tau+1] * (durability[i] - found[x])
                found[x+1] = durability[i]
            if idempotent is not None:
                found[idempotent] = durability[i]
            else:
                found[i+1] = durability[i] + float((durability[i] - grid[tau+1] + grid[tau+2]) + grid[tau+1] ** 2) / (grid[tau+2] - grid[tau+1])
            tau = x
        else:
            tau += 1
    return found[-1]

