def min_path_value(N, NSP, Q, edges, costs, special_nodes, queries):
    # Build the graph and adjacency lists
    graph = [[] for _ in range(N + 1)]  # +1 for sink
    for u, v in edges:
        graph[u].append((v, costs[u - 1]))
        graph[v].append((u, costs[v - 1]))
    for special in special_nodes:
        if special <= N:
            graph[special].append((N + 1, costs[special - 1]))  # sink
            graph[N + 1].append((special, 0))  # sink

    # Dijkstra's algorithm to find shortest paths from each node to the terminal node N+1
    distances = [float('inf')] * (N + 2)
    distances[N + 1] = 0
    priority_queue = [(0, N + 1)]
    while priority_queue:
        _, u = heappop(priority_queue)
        if u == N + 1:
            break
        for v, weight in graph[u]:
            if distances[u] + weight < distances[v]:
                heappush(priority_queue, (distances[u] + weight, v))

    # Floyd-Warshall algorithm to find shortest paths between all pairs of nodes
    for k in range(1, N + 2):
        for u in range(1, N + 2):
            for v in range(1, N + 2):
