from collections import defaultdict
from typing import List

def find_parent(parent, i):
    if parent[i] == -1:
        return i
    return find_parent(parent, parent[i])

def union_parent(parent, i, j):
    x = find_parent(parent, i)
    y = find_parent(parent, j)
    if x != y:
        parent[x] = y

def getId(u, p):
    for i in range(len(p)):
        if p[i] == u:
            return i

class Solution:
    def __init__(self):
        self.parent = defaultdict(int)

    def swap_values(self, i, j, p):
        i_idx = getId(i, self.parent)
        j_idx = getId(j, self.parent)

        self.parent[i] = self.parent[j]
        self.parent[j] = p
        p = i_idx

        return p

    def find_mex(self, n, p):
        mex = len(p)
        stack = [0]

        while mex > 0:
            value = stack.pop()
            if value == mex:
                mex -= 1
            else:
                stack.append(mex)

        return mex

    def find_kth_largest(self, n, p, i, j):
        i_idx = getId(i, self.parent)
        j_idx = getId(j, self.parent)

        self.swap_values(i_idx, j_idx, p)

        mex = len(p)
        mxv = len({self.parent[x] for x in range(len(p))})

        if i_idx <= j_idx:
            return max(mex, mxv)
        return max(0, len(p) - max(mex, mxv))

