                    count += 1
            else: 
                count += routes[0][0].count(u)
                break;

    index = max(ind[0] for ind in routes) - 2
    paths = defaultdict(list)
    for i in reversed(range(index)):
        u, v = routes[i]
        while u < len(contour) and contour[u] == u: 
            paths[contour[u]].extend([u, u]) 
            u = routes[i][1].index(u) + 1
        contour[u] = i

    maxR = max(maxR, len(contour) - len(paths.max()))
    if maxR > maxC: 
        return paths[0][0], count
    else: 
        return maxR, maxC

def solutions(edges):
    root, counter = -1, -1
    for u, v in zip(*[iter(edges)]*2):
        if counter == -1:
            root = counter = u
            continue
        if g.get(u, None) == g.get(v, None):
            maxR = maxRVal, maxC = dfs(root, counter, iMaxR=1) 
            minR = 0, doUnion(g, g[u].pop(), g[u][1], revg, u, counter, 0 if root > u else 1)
            return (minR, maxR)
        g[u].append(v)
        g[v].append(u)
        revg[v].append(u)
        revg[u].append(v)
        counter += 1
    if root == -1:
        return -1, -1
    root = [root, root]
    routes = {root: dfs(route) for route in g[root]}
    iMaxR, iMaxC = routes[root]
    return (iMaxC, iMaxR[0]) if iMaxR[0] > (iMaxR[1] - iMaxC) else (-1, -1)

for _ in range(int(input().strip())):    
    N, _ = map(int, input().strip().split())
    edges = [tuple(map(int, input().strip().split())) for _ in range(N-1)]
    print(*solutions(edges))
